/**
 * SafeImage Component
 *
 * Renders an image with a robust fallback mechanism. If the primary `src` fails
 * to load, it displays a placeholder generated by placehold.co.
 *
 * This component centralizes image error handling, keeping other components cleaner.
 */
import { useState } from 'react';
import PropTypes from 'prop-types';

const SafeImage = ({ src, alt, className, fallbackText = '?' }) => {
  const [hasError, setHasError] = useState(false);

  const handleError = () => {
    setHasError(true);
  };

  // Use a placeholder service for the fallback URL.
  // The dimensions are hardcoded for simplicity, assuming cards have fixed sizes.
  const fallbackSrc = `https://placehold.co/120x120/1A1A1A/FFFFFF?text=${encodeURIComponent(
    fallbackText
  )}`;

  return (
    <img
      src={hasError ? fallbackSrc : src}
      alt={alt}
      className={className}
      onError={handleError}
      loading="lazy" // Improve performance by lazy-loading images
    />
  );
};

SafeImage.propTypes = {
  /** The primary source URL for the image. */
  src: PropTypes.string.isRequired,
  /** The alternative text for the image, for accessibility. */
  alt: PropTypes.string.isRequired,
  /** CSS classes to apply to the image element. */
  className: PropTypes.string,
  /** The character or text to display in the fallback placeholder. */
  fallbackText: PropTypes.string,
};

export default SafeImage;
